package vn.iotstar.service.impl; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import vn.iotstar.dto.ProductDTO; import vn.iotstar.entity.*; import vn.iotstar.mapper.ProductMapper; import vn.iotstar.repository.*; import vn.iotstar.service.*; @Service @RequiredArgsConstructor public class ProductServiceImpl implements ProductService{private final ProductRepository repo;private final UserRepository users;private final ProductMapper mapper;private final CloudinaryService cloudinary; public Page<ProductDTO> findAll(String k,int p,int s){Pageable pg=PageRequest.of(Math.max(p,0),Math.max(s,1),Sort.by(Sort.Direction.DESC,"id"));return repo.search(k==null?"":k,pg).map(mapper::toDTO);} public ProductDTO findById(Long id){return mapper.toDTO(repo.findById(id).orElseThrow(()->new IllegalArgumentException("Product không tồn tại")));} @Transactional public ProductDTO create(ProductDTO d,MultipartFile image){User u=users.findById(d.getUserId()).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));Product p=mapper.toEntity(d);p.setUser(u);if(image!=null&&!image.isEmpty()){CloudinaryUploadResult r=cloudinary.upload(image);p.setImageUrl(r.url()+"|"+r.publicId());}return mapper.toDTO(repo.save(p));} @Transactional public ProductDTO update(Long id,ProductDTO d,MultipartFile image){Product p=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Product không tồn tại"));p.setName(d.getName());p.setDescription(d.getDescription());p.setPrice(d.getPrice());if(image!=null&&!image.isEmpty()){if(p.getImageUrl()!=null&&p.getImageUrl().contains("|"))cloudinary.delete(p.getImageUrl().substring(p.getImageUrl().indexOf('|')+1));CloudinaryUploadResult r=cloudinary.upload(image);p.setImageUrl(r.url()+"|"+r.publicId());}return mapper.toDTO(repo.save(p));} public void delete(Long id){Product p=repo.findById(id).orElseThrow();if(p.getImageUrl()!=null&&p.getImageUrl().contains("|"))cloudinary.delete(p.getImageUrl().substring(p.getImageUrl().indexOf('|')+1));repo.delete(p);} public long countProducts(){return repo.count();} public long countByUser(Long id){return repo.countByUserId(id);}}